import React, { useState, useEffect } from 'react';
import { Box, Button, FormControl, FormLabel, Input, Textarea, VStack, useToast } from '@chakra-ui/react';
import { api } from '../services/api';
import { Note } from '../types';

interface NoteEditorProps {
  note: Note | null;
  onFinishEdit: () => void;
}

export const NoteEditor: React.FC<NoteEditorProps> = ({ note, onFinishEdit }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const toast = useToast();

  useEffect(() => {
    if (note) {
      setTitle(note.title);
      setContent(note.content);
    } else {
      setTitle('');
      setContent('');
    }
  }, [note]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (note) {
        await api.updateNote(note.id.toString(), { title, content });
        toast({
          title: "Note updated",
          status: "success",
          duration: 3000,
          isClosable: true,
        });
      } else {
        await api.createNote({ title, content });
        toast({
          title: "Note created",
          status: "success",
          duration: 3000,
          isClosable: true,
        });
      }
      setTitle('');
      setContent('');
      onFinishEdit();
    } catch (error) {
      toast({
        title: "Error saving note",
        status: "error",
        duration: 3000,
        isClosable: true,
      });
    }
  };

  return (
    <Box as="form" onSubmit={handleSubmit}>
      <VStack spacing={4}>
        <FormControl>
          <FormLabel>Title</FormLabel>
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Note title"
          />
        </FormControl>
        <FormControl>
          <FormLabel>Content</FormLabel>
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Write your note here..."
            rows={6}
          />
        </FormControl>
        <Button type="submit" colorScheme="blue">
          {note ? 'Update Note' : 'Save Note'}
        </Button>
      </VStack>
    </Box>
  );
};
